//! Audit-only randomized model for `MembershipState::update_committed`.
//!
//! The snapshot membership must replace a purged effective membership, must
//! only replace a still-backed effective membership when it is newer, and
//! must advance (never regress) the committed membership.

use std::sync::Arc;

use maplit::btreeset;

use crate::EffectiveMembership;
use crate::LogId;
use crate::Membership;
use crate::MembershipState;

struct Lcg(u64);

impl Lcg {
    fn next(&mut self) -> u64 {
        self.0 = self.0.wrapping_mul(6364136223846793005).wrapping_add(1442695040888963407);
        self.0 >> 33
    }

    fn below(&mut self, n: u64) -> u64 {
        self.next() % n
    }
}

fn log_id(index: u64) -> LogId<u64> {
    LogId::default().set_index(index)
}

fn mem(n: u64) -> Membership<u64, ()> {
    let set = (0..n).collect::<std::collections::BTreeSet<_>>();
    Membership::new(vec![set], None)
}

fn eff(index: u64, m: Membership<u64, ()>) -> Arc<EffectiveMembership<u64, ()>> {
    Arc::new(EffectiveMembership::new(Some(log_id(index)), m))
}

#[test]
fn audit_update_committed_model() {
    for seed in 0..2000 {
        let mut rng = Lcg(seed);
        let snap = 1 + rng.below(12);
        let committed_idx = rng.below(snap);
        let committed_mem_idx = rng.below(committed_idx + 1);
        let effective_idx = committed_idx + rng.below(13 - committed_idx);

        let committed_m = mem(1 + rng.below(3));
        let effective_m = mem(1 + rng.below(3));
        let c_idx = committed_mem_idx + rng.below(snap - committed_mem_idx + 1);
        let c_m = mem(1 + rng.below(3));

        let committed = eff(committed_mem_idx, committed_m.clone());
        let effective = eff(effective_idx, effective_m.clone());
        let c = eff(c_idx, c_m.clone());

        let mut state = MembershipState::<u64, ()>::new(committed.clone(), effective.clone());
        let old_committed_log_id = state.committed().log_id().clone();

        let changed = state.update_committed(c.clone(), snap);
        let effective_idx_now = effective.log_id().index().unwrap_or(0);
        let early = effective_idx_now <= snap;
        let c_idx_now = c.log_id().index().unwrap_or(0);

        let replace_effective = early || c_idx_now >= effective_idx_now;
        let expected_effective = if replace_effective { c.clone() } else { effective.clone() };
        let expected_committed = if early {
            c.clone()
        } else if c.log_id() > committed.log_id() {
            c.clone()
        } else {
            committed.clone()
        };
        let expected_changed = if early {
            c.membership() != effective.membership()
        } else if c_idx_now >= effective_idx_now {
            c.membership() != effective.membership()
        } else {
            false
        };

        assert_eq!(
            expected_effective, **state.effective(),
            "seed {seed}: effective; committed_idx {committed_idx}, effective_idx {effective_idx}, c_idx {c_idx}, snap {snap}"
        );
        assert_eq!(
            expected_committed, **state.committed(),
            "seed {seed}: committed; committed_idx {committed_idx}, effective_idx {effective_idx}, c_idx {c_idx}, snap {snap}"
        );
        assert_eq!(expected_changed, changed.is_some(), "seed {seed}: changed signal");
        if let Some(x) = changed {
            assert_eq!(expected_effective, *x, "seed {seed}: returned effective membership");
        }
        assert!(
            state.committed().log_id() >= &old_committed_log_id,
            "seed {seed}: committed membership log id regressed from {:?} to {:?}",
            old_committed_log_id,
            state.committed().log_id()
        );
    }
}
